import React, { useState } from "react";
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from "react-router-dom";
import "./styles.css";

// Home Page Component
const HomePage = () => {
  return (
    <div className="homePage">
      <h1 className="heading">Welcome to Binance Clone</h1>
      <Link to="/login">
        <button className="button">Get Started</button>
      </Link>
    </div>
  );
};

// Login Page Component
const LoginPage = ({ onLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = () => {
    if (!username || !password) {
      alert("Please fill in all fields.");
      return;
    }
    onLogin(); // Call the onLogin function passed as a prop
  };
  

  return (
    <div className="loginPage">
      <h2 className="heading">Login</h2>
      <input
        type="text"
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <button onClick={handleLogin} className="button">
        Login
      </button>
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot Password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign Up
        </Link>
      </p>
    </div>
  );
};

// Signup Page Component
const SignupPage = ({ onSignup }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");

  const handleSignup = () => {
    if (!email || !password || !phone) {
      alert("Please fill in all fields.");
      return;
    }
  
    if (password.length < 8) {
      alert("Password must be at least 8 characters long.");
      return;
    }
  
    const phoneRegex = /^\+92\d{9}$/;
    if (!phoneRegex.test(phone)) {
      alert("Invalid phone number. Please use the format +92XXXXXXXXX.");
      return;
    }
  
    onSignup({ email, password, phone });
  };
  

  return (
    <div className="signupPage">
      <h2 className="heading">Sign Up</h2>
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password (min 8 characters)"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      <button onClick={handleSignup} className="button">
        Sign Up
      </button>
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
    </div>
  );
};

// KYC Form Component
const KYCForm = ({ onKYCSubmit }) => {
  const [name, setName] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [documentType, setDocumentType] = useState("passport");
  const [picture, setPicture] = useState(null);

  const handleSubmit = () => {
    if (!name || !phoneNumber || !picture) {
      alert("Please fill in all fields.");
      return;
    }
  
    console.log("Submitting KYC with:", { name, phoneNumber, documentType, picture });
    onKYCSubmit();
  };
  

  return (
    <div className="kycPage">
      <h2 className="heading">KYC Verification</h2>
      <input
        type="text"
        placeholder="Full Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number"
        value={phoneNumber}
        onChange={(e) => setPhoneNumber(e.target.value)}
        className="input"
      />
      <select
        value={documentType}
        onChange={(e) => setDocumentType(e.target.value)}
        className="input"
      >
        <option value="passport">Passport</option>
        <option value="driver_license">Driver's License</option>
        <option value="ID_card">ID Card</option>
        <option value="picture">Picture</option>
      </select>
      <input
        type="file"
        onChange={(e) => setPicture(e.target.files[0])}
        className="input"
      />
      <button onClick={handleSubmit} className="button">
        Submit
      </button>
    </div>
  );
};

const ForgotPasswordPage = () => {
  const [input, setInput] = useState("");

  const handleReset = () => {
    if (!input) {
      alert("Please enter your email, phone, or username.");
      return;
    }
    alert("A password reset link has been sent to your email or phone.");
  };

  return (
    <div className="forgotPasswordPage">
      <h2 className="heading">Forgot Password?</h2>
      <p>Trouble logging in?</p>
      <p>Enter your email, phone, or username and we'll send you a link to get back into your account.</p>
      <input
        type="text"
        placeholder="Email, Phone, or Username"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        className="input"
      />
      <button onClick={handleReset} className="button">Reset Password</button>
      <p className="linkText">
        <Link to="/login" className="link">Back to Login</Link>
      </p>
    </div>
  );
};

// Dashboard Component
const Dashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState("transfer");
  const [walletId, setWalletId] = useState("");
  const [receiverWalletId, setReceiverWalletId] = useState("");
  const [amount, setAmount] = useState("");
  const [totalCoins, setTotalCoins] = useState(1000); // Example: User starts with 1000 coins
  const [notification, setNotification] = useState("");
  const [transactionHistory, setTransactionHistory] = useState([]);
  const [conversionType, setConversionType] = useState("coinToUsd");
  const [conversionAmount, setConversionAmount] = useState("");
  const [conversionResult, setConversionResult] = useState("");

  const handleTransfer = () => {
    if (!walletId || !receiverWalletId || !amount) {
      setNotification("Please fill all fields.");
      return;
    }

    if (parseInt(amount) > totalCoins) {
      setNotification("Insufficient coins.");
      return;
    }

    // Simulate transfer logic
    const newTransaction = {
      id: transactionHistory.length + 1,
      from: walletId,
      to: receiverWalletId,
      amount: parseInt(amount),
      date: new Date().toLocaleString(),
      type: "Transfer",
      status: "Completed",
    };

    setTransactionHistory([...transactionHistory, newTransaction]);
    setTotalCoins(totalCoins - parseInt(amount));
    setNotification("Transfer successful!");
    setWalletId("");
    setReceiverWalletId("");
    setAmount("");
  };

  const handleConversion = () => {
    const rate = 2000; // 1 ETH = $2000
    if (conversionType === "coinToUsd") {
      setConversionResult(`$${(conversionAmount * rate).toFixed(2)}`);
    } else {
      setConversionResult(`${(conversionAmount / rate).toFixed(6)} ETH`);
    }
  };

  return (
    <div className="dashboard">
      <h2 className="heading">Dashboard</h2>
      {notification && <div className="notification">{notification}</div>}
      <div className="tabs">
        <button
          onClick={() => setActiveTab("transfer")}
          className={activeTab === "transfer" ? "activeTab" : "tab"}
        >
          Transfer Coins
        </button>
        <button
          onClick={() => setActiveTab("total")}
          className={activeTab === "total" ? "activeTab" : "tab"}
        >
          Total Coins
        </button>
        <button
          onClick={() => setActiveTab("history")}
          className={activeTab === "history" ? "activeTab" : "tab"}
        >
          Transaction History
        </button>
        <button
          onClick={() => setActiveTab("conversion")}
          className={activeTab === "conversion" ? "activeTab" : "tab"}
        >
          Coin Conversion
        </button>
      </div>

      {activeTab === "transfer" && (
        <div className="transferTab">
          <h3>Transfer Coins</h3>
          <input
            type="text"
            placeholder="Your Wallet ID"
            value={walletId}
            onChange={(e) => setWalletId(e.target.value)}
            className="input"
          />
          <input
            type="text"
            placeholder="Receiver Wallet ID"
            value={receiverWalletId}
            onChange={(e) => setReceiverWalletId(e.target.value)}
            className="input"
          />
          <input
            type="number"
            placeholder="Amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="input"
          />
          <button onClick={handleTransfer} className="button">
            Transfer
          </button>
        </div>
      )}

      {activeTab === "total" && (
        <div className="totalTab">
          <h3>Total Coins</h3>
          <p>You have {totalCoins} coins.</p>
        </div>
      )}

      {activeTab === "history" && (
        <div className="historyTab">
          <h3>Transaction History</h3>
          {transactionHistory.length === 0 ? (
            <p>No transactions yet.</p>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Date/Time</th>
                  <th>Type</th>
                  <th>Amount</th>
                  <th>Target Wallet</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {transactionHistory.map((transaction) => (
                  <tr key={transaction.id}>
                    <td>{transaction.date}</td>
                    <td>{transaction.type}</td>
                    <td>{transaction.amount}</td>
                    <td>{transaction.to}</td>
                    <td>{transaction.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === "conversion" && (
        <div className="conversionTab">
          <h3>Coin Conversion</h3>
          <p>Total Coins: {totalCoins}</p>
          <select
            value={conversionType}
            onChange={(e) => setConversionType(e.target.value)}
            className="input"
          >
            <option value="coinToUsd">Coin to USD</option>
            <option value="usdToCoin">USD to Coin</option>
          </select>
          <input
            type="number"
            placeholder="Amount"
            value={conversionAmount}
            onChange={(e) => setConversionAmount(e.target.value)}
            className="input"
          />
          <button onClick={handleConversion} className="button">
            Convert
          </button>
          {conversionResult && <p>Result: {conversionResult}</p>}
        </div>
      )}
    </div>
  );
};

// App Component
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isKYCSubmitted, setIsKYCSubmitted] = useState(false);
  const [user, setUser] = useState(null);

  const handleLogin = () => {
    setIsLoggedIn(true); // Simulate a successful login
  };

  const handleSignup = (userData) => {
    console.log("User signed up:", userData);
    setUser(userData);
    setIsLoggedIn(true); // Automatically log in after signup
  };

  const handleKYCSubmit = () => {
    setIsKYCSubmitted(true); // Simulate KYC submission
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/login"
            element={
              isLoggedIn ? (
                <Navigate to="/kyc" /> // Redirect to KYC if logged in
              ) : (
                <LoginPage onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/signup"
            element={<SignupPage onSignup={handleSignup} />}
          />
          <Route
            path="/kyc"
            element={
              isKYCSubmitted ? (
                <Navigate to="/dashboard" /> // Redirect to Dashboard after KYC submission
              ) : isLoggedIn ? (
                <KYCForm onKYCSubmit={handleKYCSubmit} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/dashboard"
            element={isKYCSubmitted ? <Dashboard user={user} /> : <Navigate to="/login" />}
          />
        </Routes>
      </div>
    </Router>
  );
};



export default App;
